**1. Technology choice: HTMLAudioElement for each sound**  
On low-end Android, Web Audio API adds ~30ms setup latency per sound and more memory. Audio sprites waste bandwidth if you need simultaneous playback (rare but possible).  
5x `<audio>` elements preloaded with `preload="metadata"` gives instant playback (<5ms latency) and is GC-friendly. Create them on mount, reuse forever.

**2. Autoplay unlock**  
Mobile browsers require a user gesture before `play()` works. Minimal fix:  
- On first user interaction (click/touch), call `.play()` then immediately `.pause()` on each audio element.  
- This unlocks the audio context for the rest of the session.  
- Do this inside a `useEffect` that attaches a one‑time event listener.

**3. Rapid trigger handling**  
For each sound, keep two `<audio>` clones (A and B). Toggle between them on each play. If one is playing, play the other. This prevents cut‑off.  
Reset `.currentTime = 0` before each play to avoid stacking.

**4. File format & encoding**  
Use **OPUS** inside OGG container (.ogg).  
- 32–48 kbps mono, 22050 Hz sample rate.  
- 200–500 ms files → each sound ~2–5 KB.  
- Total well under 100 KB.  
- Opus gives excellent low‑bitrate quality for short blips.

**5. vite-plugin-pwa Workbox globPatterns**  
Add to `vite.config.ts`:

```ts
// vite.config.ts
VitePWA({
  workbox: {
    globPatterns: [
      '**/*.{js,css,html,ico,png,svg,webp}',
      '**/*.ogg' // add this
    ]
  }
})
```

Make sure audio files are in `public/` or the build output.

**6. Minimal React hook**  

```tsx
// useSound.ts
import { useRef, useEffect, useCallback } from 'react';
import { liteMode } from './performanceStore'; // your Lite Mode boolean

type SoundKey = 'add' | 'remove' | 'confirm' | 'error' | 'panel';

export function useSound() {
  const pools = useRef<Record<SoundKey, HTMLAudioElement[]>>({
    add: [],
    remove: [],
    confirm: [],
    error: [],
    panel: []
  });

  const unlocked = useRef(false);

  // Create two audio elements per sound
  useEffect(() => {
    if (typeof window === 'undefined') return;

    const sounds: Record<SoundKey, string> = {
      add: '/sounds/add.ogg',
      remove: '/sounds/remove.ogg',
      confirm: '/sounds/confirm.ogg',
      error: '/sounds/error.ogg',
      panel: '/sounds/panel.ogg'
    };

    Object.entries(sounds).forEach(([key, src]) => {
      const pool: HTMLAudioElement[] = [];
      for (let i = 0; i < 2; i++) {
        const audio = new Audio(src);
        audio.preload = 'metadata';
        audio.volume = 0.4;
        pool.push(audio);
      }
      pools.current[key as SoundKey] = pool;
    });

    // Unlock on first user interaction
    const unlock = () => {
      if (unlocked.current) return;
      Object.values(pools.current).flat().forEach(audio => {
        audio.play().then(() => audio.pause()).catch(() => {});
      });
      unlocked.current = true;
      document.removeEventListener('click', unlock);
      document.removeEventListener('touchstart', unlock);
    };

    document.addEventListener('click', unlock, { once: true });
    document.addEventListener('touchstart', unlock, { once: true });

    return () => {
      document.removeEventListener('click', unlock);
      document.removeEventListener('touchstart', unlock);
    };
  }, []);

  const play = useCallback((key: SoundKey) => {
    if (liteMode || !unlocked.current) return;

    const pool = pools.current[key];
    if (!pool || pool.length === 0) return;

    // Find an audio element that is not currently playing
    let audio = pool.find(a => a.paused || a.ended);
    if (!audio) audio = pool[0]; // fallback to first

    audio.currentTime = 0;
    audio.play().catch(() => { /* ignore autoplay errors */ });
  }, []);

  return { play };
}
```

**Usage in component:**

```tsx
function AddButton() {
  const { play } = useSound();
  const handleClick = () => {
    // ... your logic
    play('add');
  };
  return <button onClick={handleClick}>Add</button>;
}
```
